use std::process::Command;
use std::io::{self, Write};

/// Execute a system command and return its output
/// 
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Vector of arguments for the command
/// 
/// # Returns
/// * `Result<String, String>` - Ok with stdout if successful, Err with error message if failed
pub fn execute_command(command: &str, args: Vec<&str>) -> Result<String, String> {
    let output = Command::new(command)
        .args(&args)
        .output()
        .map_err(|e| format!("Failed to execute command: {}", e))?;

    if output.status.success() {
        let stdout = String::from_utf8_lossy(&output.stdout);
        Ok(stdout.to_string())
    } else {
        let stderr = String::from_utf8_lossy(&output.stderr);
        Err(stderr.to_string())
    }
}

/// Execute a shell command through the system shell
/// 
/// # Arguments
/// * `shell_command` - The full shell command to execute
/// 
/// # Returns
/// * `Result<String, String>` - Ok with output if successful, Err with error message if failed
pub fn execute_shell_command(shell_command: &str) -> Result<String, String> {
    let output = if cfg!(target_os = "windows") {
        Command::new("cmd")
            .args(&["/C", shell_command])
            .output()
    } else {
        Command::new("sh")
            .args(&["-c", shell_command])
            .output()
    }.map_err(|e| format!("Failed to execute shell command: {}", e))?;

    if output.status.success() {
        let stdout = String::from_utf8_lossy(&output.stdout);
        Ok(stdout.to_string())
    } else {
        let stderr = String::from_utf8_lossy(&output.stderr);
        Err(stderr.to_string())
    }
}

